states.84da62b694f5:
[
 {
  "ts": "2026-09-28 09:14",
  "author": "Femke Dijkstra (Credit Analyst)",
  "text": "Quarter-end staging prep for Koelhof Cold Chain B.V. Engine output: Stage 1. Lifetime PD at origination (Nov 2023) 2.1%, current lifetime PD 5.7%. No arrears, not on the Credit Watchlist, no forbearance flag."
 },
 {
  "ts": "2026-09-28 09:20",
  "author": "Sven Okonkwo-Brandt (Relationship Manager)",
  "text": "Heads-up: I had Jeroen, their CFO, on the phone on Friday. He said they'd 'probably be tight on leverage at year-end, maybe even a breach' if the new Venlo warehouse doesn't fill up. Nothing in writing."
 },
 {
  "ts": "2026-09-28 09:26",
  "author": "Femke Dijkstra (Credit Analyst)",
  "text": "Their Q3 compliance certificate, signed by Jeroen on 22 Sep, shows net leverage 3.4x vs the 3.75x maximum and says 'management expects to remain in compliance with all financial covenants for the next 12 months'."
 },
 {
  "ts": "2026-09-28 09:31",
  "author": "Marit Vos (Senior Credit Officer)",
  "text": "I also see the margin moved from EURIBOR + 2.10% to EURIBOR + 2.175% on 1 July. Is that a modification we need to assess for forbearance?"
 },
 {
  "ts": "2026-09-28 09:35",
  "author": "Femke Dijkstra (Credit Analyst)",
  "text": "No, that's the sustainability-linked ratchet in clause 9.4 of the facility agreement: +7.5 bps if the annual Scope 1 emissions KPI is missed. They missed the 2025 target because of the old reefer truck fleet. It's automatic, agreed at signing, and the borrower didn't ask for anything."
 },
 {
  "ts": "2026-09-28 09:40",
  "author": "Marit Vos (Senior Credit Officer)",
  "text": "Policy reminder, SP-7 section 4.2: a judgmental transfer to Stage 2 is allowed where credible obligor-specific evidence shows a significant increase in credit risk that the PD does not yet capture, e.g. the borrower's own forecast of a covenant breach within the next two quarters. Second-hand remarks should be corroborated before we rely on them."
 },
 {
  "ts": "2026-09-28 09:44",
  "author": "Sven Okonkwo-Brandt (Relationship Manager)",
  "text": "I can ask Jeroen for the Q4 forecast pack this week. FYI Venlo occupancy is 58% against 80% in the business plan."
 },
 {
  "ts": "2026-09-28 09:47",
  "author": "Marit Vos (Senior Credit Officer)",
  "text": "OK. Femke, keep the engine stage for now but log the item; we revisit when the forecast pack arrives. PD ratio is about 2.7x, so close to the 3x backstop, keep an eye on it."
 }
]
